head.script:
// ====== CẤU HÌNH: sửa cho đúng môi trường của bạn ======
scwin.API_BASE      = "http://localhost:8081";          // địa chỉ backend Spring Boot
scwin.PAGE_REGISTER = "/authPage/Register.xml";      // trang đăng ký
scwin.PAGE_HOME     = "";                               // trang chính sau khi đăng nhập (để trống nếu chưa có)

scwin.onpageload = function () {
	ibx_username.focus();
};

// Hiện / ẩn thông báo
scwin.showMsg = function (text, isSuccess) {
	txt_msg.setValue(text);
	txt_msg.removeClass("is-error");
	txt_msg.removeClass("is-success");
	txt_msg.addClass(isSuccess ? "is-success" : "is-error");
	txt_msg.setStyle("display", "block");
};
scwin.hideMsg = function () {
	txt_msg.setStyle("display", "none");
};

// Lấy thông báo lỗi từ JSON backend trả về
scwin.getErrorText = function (json) {
	if (json && json.data && typeof json.data === "object") {
		for (var field in json.data) {
			if (json.data.hasOwnProperty(field)) { return json.data[field]; }
		}
	}
	return (json && json.message) ? json.message : "Có lỗi xảy ra, vui lòng thử lại.";
};

scwin.btn_login_onclick = function () {
	var username = (ibx_username.getValue() || "").trim();
	var password = sct_password.getValue() || "";
	var remember = chk_remember.getValue() === "Y";

	if (username === "") { scwin.showMsg("Vui lòng nhập tên đăng nhập hoặc email."); ibx_username.focus(); return; }
	if (password === "") { scwin.showMsg("Vui lòng nhập mật khẩu."); sct_password.focus(); return; }

	scwin.hideMsg();
	btn_login.setDisabled(true);

	fetch(scwin.API_BASE + "/api/auth/login", {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify({ username: username, password: password, rememberMe: remember })
	}).then(function (res) {
		return res.json();
	}).then(function (json) {
		btn_login.setDisabled(false);
		if (!json || !json.success) {
			scwin.showMsg(scwin.getErrorText(json));
			return;
		}
		// Lưu token: "ghi nhớ" -> localStorage, ngược lại chỉ giữ trong phiên trình duyệt
		var store = remember ? window.localStorage : window.sessionStorage;
		window.localStorage.removeItem("ssc_token");
		window.sessionStorage.removeItem("ssc_token");
		store.setItem("ssc_token", json.data.accessToken);
		store.setItem("ssc_user", JSON.stringify(json.data.user));

		scwin.showMsg("Đăng nhập thành công. Xin chào " + json.data.user.fullName + "!", true);
		if (scwin.PAGE_HOME !== "") {
			setTimeout(function () { $p.url(scwin.PAGE_HOME); }, 600);
		}
	}).catch(function () {
		btn_login.setDisabled(false);
		scwin.showMsg("Không kết nối được máy chủ. Vui lòng kiểm tra backend đang chạy.");
	});
};

// Nhấn Enter để đăng nhập
scwin.form_onkeyup = function (e) {
	if (e && e.keyCode === 13) { scwin.btn_login_onclick(); }
};

scwin.lnk_register_onclick = function () {
	$p.url(scwin.PAGE_REGISTER);
};
